#include <atomic>
#include <cstdint>
#include <format>
#include <iostream>
#include <memory>

struct Pose {
  double x = 0.0;
  double y = 0.0;
};

struct Reading {
  std::int32_t value = 0;
  std::int32_t age = 0;
};

int main() {
  std::cout << std::format("{:<28} {:>5} {:>6}\n", "type", "bytes", "free");
  std::cout << std::format("{:<28} {:>5} {:>6}\n", "atomic_flag", sizeof(std::atomic_flag), true);
  std::cout << std::format("{:<28} {:>5} {:>6}\n", "atomic<bool>", sizeof(std::atomic<bool>),
                           std::atomic<bool>::is_always_lock_free);
  std::cout << std::format("{:<28} {:>5} {:>6}\n", "atomic<int>", sizeof(std::atomic<int>),
                           std::atomic<int>::is_always_lock_free);
  std::cout << std::format("{:<28} {:>5} {:>6}\n", "atomic<int64_t>", sizeof(std::atomic<std::int64_t>),
                           std::atomic<std::int64_t>::is_always_lock_free);
  std::cout << std::format("{:<28} {:>5} {:>6}\n", "atomic<double>", sizeof(std::atomic<double>),
                           std::atomic<double>::is_always_lock_free);
  std::cout << std::format("{:<28} {:>5} {:>6}\n", "atomic<Reading> (two int32)", sizeof(std::atomic<Reading>),
                           std::atomic<Reading>::is_always_lock_free);
  std::cout << std::format("{:<28} {:>5} {:>6}\n", "atomic<Pose> (two double)", sizeof(std::atomic<Pose>),
                           std::atomic<Pose>::is_always_lock_free);
  std::cout << std::format("{:<28} {:>5} {:>6}\n", "atomic<shared_ptr<Pose>>",
                           sizeof(std::atomic<std::shared_ptr<Pose>>),
                           std::atomic<std::shared_ptr<Pose>>::is_always_lock_free);
}

#include <atomic>
#include <cstdint>
#include <format>
#include <iostream>
#include <thread>
#include <vector>

struct Scan {
  std::int64_t beams = 0;
};

struct Totals {
  std::int64_t received = 0;
  std::int64_t dropped = 0;
  std::int64_t beams = 0;
};

// Three counters that any number of sensor threads may update at once.
class ScanStats {
 public:
  // Relaxed: nothing is published through these counters, so only the count has to be exact.
  void record(Scan scan) {
    received_.fetch_add(1, std::memory_order_relaxed);
    beams_.fetch_add(scan.beams, std::memory_order_relaxed);
  }

  void record_drop() { dropped_.fetch_add(1, std::memory_order_relaxed); }

  // Three separate reads: each one is exact, and the three together are not one moment.
  [[nodiscard]] Totals read() const {
    return {.received = received_.load(std::memory_order_relaxed),
            .dropped = dropped_.load(std::memory_order_relaxed),
            .beams = beams_.load(std::memory_order_relaxed)};
  }

 private:
  std::atomic<std::int64_t> received_{0};
  std::atomic<std::int64_t> dropped_{0};
  std::atomic<std::int64_t> beams_{0};
};

int main() {
  constexpr int kSensors = 4;
  constexpr std::int64_t kPerSensor = 5'000;
  ScanStats stats;
  {
    std::vector<std::jthread> sensors;
    sensors.reserve(kSensors);
    for (int i = 0; i < kSensors; ++i) {
      sensors.emplace_back([&stats] {
        for (std::int64_t k = 0; k < kPerSensor; ++k) {
          if (k % 10 == 0) {
            stats.record_drop();
          } else {
            stats.record({.beams = 360});
          }
        }
      });
    }
  }
  const Totals totals = stats.read();  // every sensor has been joined, so this one is consistent
  std::cout << std::format("received {}, dropped {}, beams {}\n", totals.received, totals.dropped, totals.beams);
  std::cout << std::format("received plus dropped is what was offered: {}\n",
                           totals.received + totals.dropped == kSensors * kPerSensor);
  std::cout << std::format("every received scan counted its beams: {}\n", totals.beams == totals.received * 360);
}

#include <format>
#include <future>
#include <iostream>
#include <stdexcept>
#include <string>

struct Scan {
  int beams = 0;
};

[[nodiscard]] Scan read_sensor(int beams) {
  if (beams <= 0) throw std::runtime_error("sensor offline");
  return Scan{.beams = beams};
}

int main() {
  std::future<Scan> good = std::async(std::launch::async, read_sensor, 3600);
  std::future<Scan> bad = std::async(std::launch::async, read_sensor, 0);

  std::cout << std::format("the good scan has {} beams\n", good.get().beams);
  std::cout << std::format("after get, the future still holds a result: {}\n", good.valid());

  try {
    const Scan scan = bad.get();
    std::cout << std::format("unreachable {}\n", scan.beams);
  } catch (const std::runtime_error& e) {
    std::cout << std::format("the failed scan threw on get: {}\n", e.what());
  }

  try {
    const Scan again = good.get();  // the result was taken by the first get
    std::cout << std::format("unreachable {}\n", again.beams);
  } catch (const std::future_error& e) {
    std::cout << std::format("a second get: {}\n", e.code().message());
  }

  std::future<Scan> orphan;
  {
    std::promise<Scan> promise;
    orphan = promise.get_future();
  }  // the promise is destroyed without a value
  try {
    const Scan never = orphan.get();
    std::cout << std::format("unreachable {}\n", never.beams);
  } catch (const std::future_error& e) {
    std::cout << std::format("a promise that never answered: {}\n", e.code().message());
  }
}

