#include <chrono>
#include <format>
#include <future>
#include <iostream>
#include <thread>

constexpr auto kWork = std::chrono::milliseconds(200);

void slow_step() { std::this_thread::sleep_for(kWork); }

int main() {
  // Two futures that are kept: the calls overlap.
  const auto kept_start = std::chrono::steady_clock::now();
  {
    std::future<void> first = std::async(std::launch::async, slow_step);
    std::future<void> second = std::async(std::launch::async, slow_step);
    first.get();
    second.get();
  }
  const auto kept = std::chrono::steady_clock::now() - kept_start;

  // Two futures whose scopes do not overlap: each destructor waits for its own call to finish.
  const auto dropped_start = std::chrono::steady_clock::now();
  {
    const std::future<void> first = std::async(std::launch::async, slow_step);
  }
  {
    const std::future<void> second = std::async(std::launch::async, slow_step);
  }
  const auto dropped = std::chrono::steady_clock::now() - dropped_start;

  std::cout << std::format("two steps of {} ms each\n", kWork.count());
  std::cout << std::format("futures kept, both under 150% of one step: {}\n", kept < kWork * 3 / 2);
  std::cout << std::format("futures dropped, at least two steps: {}\n", dropped >= kWork * 2);
}

#include <cstdint>
#include <exception>
#include <format>
#include <future>
#include <iostream>
#include <span>
#include <stdexcept>
#include <thread>
#include <vector>

struct Calibration {
  double offset = 0.0;
  std::int64_t samples = 0;
};

// Plain logic: no threads, no futures, so a test can call it directly.
[[nodiscard]] Calibration calibrate(std::span<const float> samples) {
  if (samples.empty()) throw std::runtime_error("no samples to calibrate from");
  double total = 0.0;
  for (const float sample : samples) total += static_cast<double>(sample);
  return {.offset = total / static_cast<double>(std::ssize(samples)), .samples = std::ssize(samples)};
}

// The handover: whatever the work does, the caller learns about it through the future.
[[nodiscard]] std::future<Calibration> calibrate_async(std::span<const float> samples, std::jthread& worker) {
  std::promise<Calibration> promise;
  std::future<Calibration> future = promise.get_future();  // taken before the promise moves away
  worker = std::jthread([samples, promise = std::move(promise)]() mutable {
    try {
      promise.set_value(calibrate(samples));
    } catch (...) {
      promise.set_exception(std::current_exception());  // the same exception, on the caller's side
    }
  });
  return future;
}

int main() {
  const std::vector<float> samples{1.0F, 2.0F, 3.0F, 4.0F};
  {
    std::jthread worker;
    std::future<Calibration> future = calibrate_async(samples, worker);
    const Calibration result = future.get();
    std::cout << std::format("offset {:.2f} from {} samples\n", result.offset, result.samples);
  }
  {
    std::jthread worker;
    std::future<Calibration> future = calibrate_async({}, worker);
    try {
      const Calibration result = future.get();
      std::cout << std::format("unreachable {:.2f}\n", result.offset);
    } catch (const std::runtime_error& e) {
      std::cout << std::format("the worker's exception arrived here: {}\n", e.what());
    }
  }
}

#include <atomic>
#include <chrono>
#include <cstdint>
#include <format>
#include <iostream>
#include <latch>
#include <thread>
#include <vector>

constexpr int kThreads = 8;

int main() {
  std::atomic<bool> claimed{false};
  std::atomic<int> winners{0};
  std::latch start(kThreads);
  {
    std::vector<std::jthread> racers;
    racers.reserve(kThreads);
    for (int i = 0; i < kThreads; ++i) {
      racers.emplace_back([&claimed, &winners, &start] {
        start.arrive_and_wait();  // every thread arrives at the test together
        if (!claimed.load()) {    // step one: read
          // Whatever a real claimant does before it records the claim: open the file, build the map.
          std::this_thread::sleep_for(std::chrono::milliseconds(5));
          claimed.store(true);  // step two: write, long after the read
          winners.fetch_add(1);
        }
      });
    }
  }
  std::cout << std::format("{} of {} threads believed they were the first\n", winners.load(), kThreads);
}

#include <atomic>
#include <cstdint>
#include <format>
#include <iostream>
#include <latch>
#include <thread>
#include <vector>

constexpr int kThreads = 8;

int main() {
  std::atomic<bool> claimed{false};
  std::atomic<int> winners{0};
  std::atomic<int> late{0};
  std::latch start(kThreads);
  {
    std::vector<std::jthread> racers;
    racers.reserve(kThreads);
    for (int i = 0; i < kThreads; ++i) {
      racers.emplace_back([&claimed, &winners, &late, &start] {
        start.arrive_and_wait();
        // One operation: it writes true and returns what was there before.
        if (!claimed.exchange(true)) {
          winners.fetch_add(1);
        } else {
          late.fetch_add(1);
        }
      });
    }
  }
  std::cout << std::format("{} winner, {} late, out of {} threads\n", winners.load(), late.load(), kThreads);
}
